-- Part 6 (diversification pass): online MCQ bank (comp_mcq_questions) for project_director
-- ("مدیر پروژه ارشد/دایرکتور"). ZERO rows before this seed (verified via the MCQ
-- count-per-role audit query). 30 questions, APPROVED and active, spanning TECHNICAL/GENERAL/
-- HSE/SCENARIO/JUDGMENT/PROBLEM_SOLVING/CASE_STUDY, difficulty 1-3, varied stem formats.
-- Domain grounding: Earned Value Management (EVM: CPI/SPI/EAC), FIDIC contract
-- administration (claims/variations/EOT), stakeholder/portfolio governance, HSE leadership
-- (process safety culture, major-accident-hazard oversight), critical path scheduling.
-- Same rotation technique as supabase/seed/mcq_questions_seed.sql. Idempotent via
-- (job_role, md5(stem_fa)) unique index.

insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
